import { createElement, render, Component } from 'preact';
import { setupScratch, teardown } from '../../../test/_util/helpers';
import { useEffect, useState } from 'preact/hooks';
import { act } from 'preact/test-utils';

/** @jsx createElement */

describe('tmp debug', () => {
	let scratch;

	beforeEach(() => {
		scratch = setupScratch();
	});

	afterEach(() => {
		teardown(scratch);
	});

	it('removes DOM when cleanup throws on update', () => {
		class ErrorBoundary extends Component {
			constructor(props) {
				super(props);
				this.state = { error: null };
			}

			componentDidCatch(error) {
				this.setState({ error: 'oh no' });
			}

			render() {
				return this.state.error ? (
					<h2>Error! {this.state.error}</h2>
				) : (
					this.props.children
				);
			}
		}

		let update;
		const MainContent = () => {
			const [val, setVal] = useState(false);
			update = () => setVal(!val);
			useEffect(() => {
				return () => {
					throw new Error('oops');
				};
			}, [val]);
			return <h1>Hello world</h1>;
		};

		act(() =>
			render(
				<ErrorBoundary>
					<MainContent />
				</ErrorBoundary>,
				scratch
			)
		);
		act(() => update());
		expect(scratch.innerHTML).to.equal('<h2>Error! oh no</h2>');
	});

	it('calls all cleanups when first throws on unmount', () => {
		const secondCleanup = sinon.spy();
		const App = () => {
			useEffect(() => {
				return () => {
					throw new Error('oops');
				};
			}, []);
			useEffect(() => {
				return () => secondCleanup();
			}, []);
			return <h1>Hello world</h1>;
		};

		render(<App />, scratch);
		try {
			render(null, scratch);
		} catch (e) {
			// expected
		}
		expect(secondCleanup).to.be.calledOnce;
		expect(scratch.innerHTML).to.equal('');
	});
});

